cat > /workspace/project/src/star4_switch.c <<'EOF'
/* Offline four-port collective collector.
 *
 * The switch is a pure replay device: it never opens a socket and never
 * touches a NIC.  Every ingress frame is validated, classified and applied to
 * the retained window; every egress frame is built here and handed to the
 * offline emit callback.
 */

#include "collector.h"
#include "epic_clean.h"

#include <arpa/inet.h>
#include <stdlib.h>
#include <string.h>

#define HOSTS EPIC_STAR4_HOSTS
#define MASK24 0x00ffffffu
#define DATA_OPCODE 0x04
#define ACK_OPCODE 0x11
#define UDP_PORT EPIC_ROCE_UDP_PORT

/* ------------------------------------------------------------------ state */

typedef struct {
    int used;
    uint32_t p;             /* logical input sequence */
    uint8_t mask;           /* accepted source bitmap */
    uint8_t complete;       /* collective input complete */
    uint8_t *raw[HOSTS];    /* allgather: per source, broadcast: root only */
    uint32_t *agg;          /* sum based primitives: D aggregate words */
} slot_t;

struct collector {
    int primitive;
    int mode;
    int root;
    uint32_t K;             /* logical segments */
    uint32_t D;             /* vector words */
    uint32_t N;             /* retained slots */
    uint32_t start;         /* physical PSN of logical sequence zero */
    uint32_t b;             /* retired prefix */
    uint32_t occupied;      /* occupied slots */
    slot_t *slots;
    uint32_t R[HOSTS];      /* received prefixes */
    uint32_t S[HOSTS];      /* new output sent prefixes */
    uint32_t A[HOSTS];      /* downstream acknowledged prefixes */
    uint32_t U[HOSTS];      /* upstream sent prefixes */
    uint8_t repeat[HOSTS];  /* pending upstream ACK repeat request */
    uint64_t st[32];        /* certificate counters */
    epic_emit_fn emit;
    void *user;
    epic_port_t ports[HOSTS];
    uint8_t *frame;         /* egress scratch */
    uint8_t *scratch;       /* payload scratch */
    size_t frame_cap;
};

/* ------------------------------------------------------------- primitives */

static uint8_t required_mask(const collector_t *c)
{
    if (c->primitive == EPIC_PRIM_BCAST) {
        return (uint8_t)(1u << c->root);
    }
    return 0x0fu;
}

static int is_destination(const collector_t *c, int rank)
{
    switch (c->primitive) {
    case EPIC_PRIM_REDUCE:
        return rank == c->root;
    case EPIC_PRIM_BCAST:
        return rank != c->root;
    default:
        return 1;
    }
}

/* number of output records owned by one destination */
static uint32_t dest_total(const collector_t *c, int rank)
{
    (void)rank;
    switch (c->primitive) {
    case EPIC_PRIM_BARRIER:
        return 1u;
    case EPIC_PRIM_ALLGATHER:
        return 3u * c->K;
    case EPIC_PRIM_REDUCESCATTER:
        return c->K / 4u;
    default:
        return c->K;
    }
}

/* ordinal of src inside the ascending rank list with dest omitted */
static int ordinal_excluding(int dest, int src)
{
    int ordinal = 0;
    for (int r = 0; r < HOSTS; r++) {
        if (r == dest) {
            continue;
        }
        if (r == src) {
            return ordinal;
        }
        ordinal++;
    }
    return 0;
}

static int rank_from_ordinal(int dest, int ordinal)
{
    int seen = 0;
    for (int r = 0; r < HOSTS; r++) {
        if (r == dest) {
            continue;
        }
        if (seen == ordinal) {
            return r;
        }
        seen++;
    }
    return 0;
}

/* ------------------------------------------------------------------ slots */

static void slot_release(collector_t *c, slot_t *s)
{
    for (int r = 0; r < HOSTS; r++) {
        free(s->raw[r]);
        s->raw[r] = NULL;
    }
    free(s->agg);
    s->agg = NULL;
    s->used = 0;
    s->mask = 0;
    s->complete = 0;
    s->p = 0;
    (void)c;
}

static slot_t *slot_find(const collector_t *c, uint32_t p)
{
    slot_t *s = &c->slots[p % c->N];
    if (s->used && s->p == p) {
        return s;
    }
    return NULL;
}

static slot_t *slot_create(collector_t *c, uint32_t p)
{
    slot_t *s = &c->slots[p % c->N];
    if (s->used) {
        /* Never expected: retained identities are logical, not p mod N. */
        c->st[30]++;
        slot_release(c, s);
        c->occupied--;
    }
    s->used = 1;
    s->p = p;
    s->mask = 0;
    s->complete = 0;
    c->occupied++;
    return s;
}

static void slot_store(collector_t *c, slot_t *s, int rank, const uint8_t *payload)
{
    size_t bytes = (size_t)c->D * 4u;
    if (c->primitive == EPIC_PRIM_ALLGATHER) {
        if (!s->raw[rank]) {
            s->raw[rank] = malloc(bytes ? bytes : 1u);
        }
        if (bytes) {
            memcpy(s->raw[rank], payload, bytes);
        }
        return;
    }
    if (c->primitive == EPIC_PRIM_BCAST) {
        int root = c->root;
        if (!s->raw[root]) {
            s->raw[root] = malloc(bytes ? bytes : 1u);
        }
        if (bytes) {
            memcpy(s->raw[root], payload, bytes);
        }
        return;
    }
    if (!s->agg) {
        s->agg = calloc(c->D ? c->D : 1u, sizeof(uint32_t));
    }
    if (c->D) {
        for (uint32_t j = 0; j < c->D; j++) {
            uint32_t v;
            memcpy(&v, payload + 4u * j, 4u);
            v = ntohl(v);
            s->agg[j] += v;
        }
    }
}

/* ------------------------------------------------------------ wire parsing */

typedef struct {
    int is_data;
    uint32_t psn;
    uint32_t qpn;
    uint32_t src_ip;
    uint32_t dst_ip;
    const uint8_t *payload;
    size_t payload_len;
} packet_t;

static int ipv4_checksum_ok(const uint8_t *ip)
{
    uint32_t sum = 0;
    for (int i = 0; i < 20; i += 2) {
        sum += ((uint32_t)ip[i] << 8) | (uint32_t)ip[i + 1];
    }
    while (sum >> 16) {
        sum = (sum & 0xffffu) + (sum >> 16);
    }
    return (uint16_t)(~sum) == 0u;
}

static int wire_valid(const collector_t *c, const uint8_t *frame, size_t len,
                      packet_t *out)
{
    memset(out, 0, sizeof(*out));
    if (!frame || len < 58u) {
        return 0;
    }
    if (frame[12] != 0x08 || frame[13] != 0x00) {
        return 0;
    }
    const uint8_t *ip = frame + 14;
    if (ip[0] != 0x45) {
        return 0;
    }
    uint16_t ip_len = (uint16_t)((ip[2] << 8) | ip[3]);
    if ((size_t)ip_len + 14u != len) {
        return 0;
    }
    if (ip[9] != 17) {
        return 0;
    }
    if (ip[6] != 0x00 && ip[6] != 0x40) {
        return 0;
    }
    if (!ipv4_checksum_ok(ip)) {
        return 0;
    }
    const uint8_t *udp = ip + 20;
    uint16_t udp_len = (uint16_t)((udp[4] << 8) | udp[5]);
    if ((uint32_t)udp_len + 20u != (uint32_t)ip_len) {
        return 0;
    }
    if (((udp[0] << 8) | udp[1]) != UDP_PORT ||
        ((udp[2] << 8) | udp[3]) != UDP_PORT) {
        return 0;
    }
    if (udp[6] != 0 || udp[7] != 0) {
        return 0;
    }
    const uint8_t *bth = udp + 8;
    uint8_t opcode = bth[0];
    if (opcode != DATA_OPCODE && opcode != ACK_OPCODE) {
        return 0;
    }
    if (bth[1] != 0) {
        return 0;
    }
    if (((bth[2] << 8) | bth[3]) != 0xffffu) {
        return 0;
    }
    uint32_t qpn = ((uint32_t)bth[4] << 24) | ((uint32_t)bth[5] << 16) |
                   ((uint32_t)bth[6] << 8) | (uint32_t)bth[7];
    if (qpn >> 24) {
        return 0;
    }
    uint32_t apsn = ((uint32_t)bth[8] << 24) | ((uint32_t)bth[9] << 16) |
                    ((uint32_t)bth[10] << 8) | (uint32_t)bth[11];
    size_t body = (size_t)udp_len - 8u - 12u - 4u;
    if (opcode == DATA_OPCODE) {
        if (apsn >> 24 != 0x80u) {
            return 0;
        }
        size_t want = (size_t)c->D * 4u;
        if (body == want) {
            out->payload = bth + 12;
            out->payload_len = want;
        } else if (body == want + 4u) {
            /* optional AETH ahead of the payload */
            out->payload = bth + 16;
            out->payload_len = want;
        } else {
            return 0;
        }
        out->is_data = 1;
    } else {
        if (apsn >> 24) {
            return 0;
        }
        if (body != 4u) {
            return 0;
        }
        uint32_t aeth = ((uint32_t)bth[12] << 24) | ((uint32_t)bth[13] << 16) |
                        ((uint32_t)bth[14] << 8) | (uint32_t)bth[15];
        if ((aeth >> 24) != 0x1fu) {
            return 0;
        }
        if ((aeth & MASK24) != ((apsn + 1u) & MASK24)) {
            return 0;
        }
        out->is_data = 0;
    }
    uint32_t stored;
    memcpy(&stored, frame + len - 4u, 4u);
    if (epic_compute_icrc(frame, len) != stored) {
        return 0;
    }
    out->psn = apsn & MASK24;
    out->qpn = qpn;
    out->src_ip = ((uint32_t)ip[12] << 24) | ((uint32_t)ip[13] << 16) |
                  ((uint32_t)ip[14] << 8) | (uint32_t)ip[15];
    out->dst_ip = ((uint32_t)ip[16] << 24) | ((uint32_t)ip[17] << 16) |
                  ((uint32_t)ip[18] << 8) | (uint32_t)ip[19];
    return 1;
}

static int endpoint_valid(const collector_t *c, int rank, const uint8_t *frame,
                           const packet_t *pkt)
{
    const epic_port_t *port = &c->ports[rank];
    if (memcmp(frame, port->host_mac, 6) != 0) {
        return 0;
    }
    if (memcmp(frame + 6, port->switch_mac, 6) != 0) {
        return 0;
    }
    if (pkt->src_ip != port->host_ip || pkt->dst_ip != port->switch_ip) {
        return 0;
    }
    if (pkt->qpn != port->switch_qpn) {
        return 0;
    }
    return 1;
}

/* --------------------------------------------------------- upstream prefix */

static uint32_t eligible_prefix(const collector_t *c, int rank)
{
    uint32_t received = c->R[rank];
    if (received == 0) {
        return 0;
    }
    if (c->mode == EPIC_MODE_TERMINATION) {
        /* accepted contributions are safe immediately */
        return received;
    }
    switch (c->primitive) {
    case EPIC_PRIM_ALLREDUCE:
    case EPIC_PRIM_BARRIER:
        return received < c->A[rank] ? received : c->A[rank];
    case EPIC_PRIM_REDUCE:
        return received < c->A[c->root] ? received : c->A[c->root];
    case EPIC_PRIM_BCAST: {
        uint32_t limit = received;
        for (int d = 0; d < HOSTS; d++) {
            if (d == c->root) {
                continue;
            }
            if (c->A[d] < limit) {
                limit = c->A[d];
            }
        }
        return limit;
    }
    case EPIC_PRIM_REDUCESCATTER: {
        uint32_t block = c->K / 4u;
        uint64_t covered = 0;
        for (int d = 0; d < HOSTS; d++) {
            uint32_t have = c->A[d] < block ? c->A[d] : block;
            covered += have;
        }
        return covered < received ? (uint32_t)covered : received;
    }
    case EPIC_PRIM_ALLGATHER: {
        uint32_t limit = received;
        for (int d = 0; d < HOSTS; d++) {
            if (d == rank) {
                continue;
            }
            uint32_t ord = (uint32_t)ordinal_excluding(d, rank);
            uint32_t ack = c->A[d];
            uint32_t covered = 0;
            if (ack > ord) {
                covered = (ack - ord + 2u) / 3u;
            }
            if (covered < limit) {
                limit = covered;
            }
        }
        return limit;
    }
    default:
        return received;
    }
}

/* --------------------------------------------------------------- emission */

static int emit_frame(collector_t *c, int rank, const uint8_t *frame, size_t len,
                      int is_data)
{
    if (!len) {
        c->st[29]++;
        return 0;
    }
    if (!c->emit(c->user, rank, frame, len)) {
        c->st[29]++;
        return 0;
    }
    c->st[is_data ? 20 : 21]++;
    return 1;
}

static int send_upstream_ack(collector_t *c, int rank, uint32_t prefix)
{
    const epic_port_t *port = &c->ports[rank];
    uint32_t psn = (c->start + prefix - 1u) & MASK24;
    size_t len = epic_build_roce_ack(c->frame, c->frame_cap, port->switch_mac,
                                      port->host_mac, port->switch_ip,
                                      port->host_ip, UDP_PORT, UDP_PORT,
                                      port->host_qpn, psn);
    return emit_frame(c, rank, c->frame, len, 0);
}

static int send_result(collector_t *c, int rank, uint32_t q)
{
    const uint8_t *payload = NULL;
    size_t payload_len = 0;
    uint32_t p = q;
    const slot_t *s = NULL;

    switch (c->primitive) {
    case EPIC_PRIM_ALLGATHER: {
        uint32_t local = q / 3u;
        int src = rank_from_ordinal(rank, (int)(q % 3u));
        p = local;
        s = slot_find(c, p);
        if (!s || !s->raw[src]) {
            return 1; /* nothing to retransmit */
        }
        payload = s->raw[src];
        payload_len = (size_t)c->D * 4u;
        break;
    }
    case EPIC_PRIM_BCAST: {
        p = q;
        s = slot_find(c, p);
        if (!s || !s->raw[c->root]) {
            return 1;
        }
        payload = s->raw[c->root];
        payload_len = (size_t)c->D * 4u;
        break;
    }
    case EPIC_PRIM_BARRIER: {
        p = 0;
        s = slot_find(c, p);
        if (!s) {
            return 1;
        }
        payload = NULL;
        payload_len = 0;
        break;
    }
    case EPIC_PRIM_REDUCESCATTER: {
        p = (uint32_t)rank * (c->K / 4u) + q;
        s = slot_find(c, p);
        if (!s) {
            return 1;
        }
        break;
    }
    default: {
        p = q;
        s = slot_find(c, p);
        if (!s) {
            return 1;
        }
        break;
    }
    }

    if (c->primitive == EPIC_PRIM_ALLREDUCE || c->primitive == EPIC_PRIM_REDUCE ||
        c->primitive == EPIC_PRIM_REDUCESCATTER) {
        size_t bytes = (size_t)c->D * 4u;
        memset(c->scratch, 0, bytes);
        if (c->D) {
            for (uint32_t j = 0; j < c->D; j++) {
                uint32_t v = s->agg[j];
                c->scratch[4u * j + 0u] = (uint8_t)(v >> 24);
                c->scratch[4u * j + 1u] = (uint8_t)(v >> 16);
                c->scratch[4u * j + 2u] = (uint8_t)(v >> 8);
                c->scratch[4u * j + 3u] = (uint8_t)v;
            }
        }
        payload = c->scratch;
        payload_len = bytes;
    }

    const epic_port_t *port = &c->ports[rank];
    uint32_t psn = (c->start + q) & MASK24;
    size_t len = epic_build_roce_data_raw(c->frame, c->frame_cap, port->switch_mac,
                                          port->host_mac, port->switch_ip,
                                          port->host_ip, UDP_PORT, UDP_PORT,
                                          port->host_qpn, psn, payload,
                                          payload_len);
    return emit_frame(c, rank, c->frame, len, 1);
}

static int result_ready(const collector_t *c, int rank, uint32_t q)
{
    uint32_t p = q;
    switch (c->primitive) {
    case EPIC_PRIM_ALLGATHER:
        p = q / 3u;
        break;
    case EPIC_PRIM_REDUCESCATTER:
        p = (uint32_t)rank * (c->K / 4u) + q;
        break;
    case EPIC_PRIM_BARRIER:
        p = 0;
        break;
    default:
        break;
    }
    const slot_t *s = slot_find(c, p);
    if (!s) {
        return 0;
    }
    if (c->primitive == EPIC_PRIM_BCAST) {
        return (s->mask & (uint8_t)(1u << c->root)) != 0;
    }
    return s->complete != 0;
}

/* The observable emission priority of one service opportunity. */
static void service(collector_t *c, int retry_rank)
{
    for (int r = 0; r < HOSTS; r++) {
        uint32_t eligible = eligible_prefix(c, r);
        if (eligible == 0) {
            continue;
        }
        if (!(eligible > c->U[r] || c->repeat[r])) {
            continue;
        }
        if (!send_upstream_ack(c, r, eligible)) {
            return;
        }
        if (eligible > c->U[r]) {
            c->U[r] = eligible;
        }
        c->repeat[r] = 0;
    }

    if (retry_rank >= 0) {
        int d = retry_rank;
        uint32_t q = c->A[d];
        while (q < c->S[d]) {
            if (!send_result(c, d, q)) {
                return;
            }
            q++;
        }
    }

    for (int d = 0; d < HOSTS; d++) {
        if (!is_destination(c, d)) {
            continue;
        }
        uint32_t total = dest_total(c, d);
        while (c->S[d] < total) {
            uint32_t q = c->S[d];
            if (!result_ready(c, d, q)) {
                break;
            }
            if (!send_result(c, d, q)) {
                return;
            }
            c->S[d]++;
        }
    }
}

/* -------------------------------------------------------------- retirement */

static int outputs_acked(const collector_t *c, uint32_t p)
{
    switch (c->primitive) {
    case EPIC_PRIM_ALLREDUCE:
    case EPIC_PRIM_BARRIER:
        for (int d = 0; d < HOSTS; d++) {
            if (c->A[d] < p + 1u) {
                return 0;
            }
        }
        return 1;
    case EPIC_PRIM_REDUCE:
        return c->A[c->root] >= p + 1u;
    case EPIC_PRIM_BCAST:
        for (int d = 0; d < HOSTS; d++) {
            if (d == c->root) {
                continue;
            }
            if (c->A[d] < p + 1u) {
                return 0;
            }
        }
        return 1;
    case EPIC_PRIM_ALLGATHER:
        for (int d = 0; d < HOSTS; d++) {
            if (c->A[d] < 3u * p + 3u) {
                return 0;
            }
        }
        return 1;
    case EPIC_PRIM_REDUCESCATTER: {
        uint32_t block = c->K / 4u;
        uint32_t d = p / block;
        uint32_t q = p % block;
        return c->A[d] >= q + 1u;
    }
    default:
        return 0;
    }
}

static void retire(collector_t *c)
{
    uint8_t need = required_mask(c);
    while (c->b < c->K) {
        slot_t *s = slot_find(c, c->b);
        if (!s || s->mask != need || !s->complete) {
            return;
        }
        if (!outputs_acked(c, c->b)) {
            return;
        }
        for (int r = 0; r < HOSTS; r++) {
            if (!(need & (uint8_t)(1u << r))) {
                continue;
            }
            if (c->U[r] <= c->b) {
                return;
            }
        }
        slot_release(c, s);
        c->occupied--;
        c->b++;
    }
}

/* ----------------------------------------------------------------- ingress */

static void advance_received(collector_t *c, int rank)
{
    while (c->R[rank] < c->K) {
        const slot_t *s = slot_find(c, c->R[rank]);
        if (!s || !(s->mask & (uint8_t)(1u << rank))) {
            break;
        }
        c->R[rank]++;
    }
}

static void classify_data(collector_t *c, int rank, uint32_t p,
                           const uint8_t *payload)
{
    if (p < c->b) {
        c->st[25]++;
        c->repeat[rank] = 1;
        return;
    }
    if (p >= c->b + c->N) {
        c->st[24]++;
        return;
    }
    slot_t *s = slot_find(c, p);
    if (s && (s->mask & (uint8_t)(1u << rank))) {
        c->st[23]++;
        c->repeat[rank] = 1;
        return;
    }
    if (!s) {
        s = slot_create(c, p);
    }
    slot_store(c, s, rank, payload);
    s->mask |= (uint8_t)(1u << rank);
    if (s->mask == required_mask(c)) {
        s->complete = 1;
    }
    c->st[22]++;
    advance_received(c, rank);
}

int collector_ingress(collector_t *c, int rank, const uint8_t *frame, size_t length)
{
    packet_t pkt;
    if (!c || rank < 0 || rank >= HOSTS) {
        return 0;
    }
    if (!wire_valid(c, frame, length, &pkt)) {
        c->st[26]++;
        return 1;
    }
    if (!endpoint_valid(c, rank, frame, &pkt)) {
        c->st[27]++;
        return 1;
    }
    if (pkt.is_data) {
        uint32_t logical = (pkt.psn - c->start) & MASK24;
        uint8_t need = required_mask(c);
        if (!(need & (uint8_t)(1u << rank)) || logical >= c->K) {
            c->st[27]++;
            return 1;
        }
        c->st[18]++;
        classify_data(c, rank, logical, pkt.payload);
    } else {
        c->st[19]++;
        uint32_t prefix = (pkt.psn - c->start + 1u) & MASK24;
        if (prefix > c->A[rank] && prefix <= c->S[rank]) {
            c->A[rank] = prefix;
        } else {
            c->st[28]++;
        }
    }
    retire(c);
    service(c, -1);
    retire(c);
    return 1;
}

int collector_flush(collector_t *c)
{
    if (!c) {
        return 0;
    }
    service(c, -1);
    retire(c);
    return 1;
}

int collector_retry(collector_t *c, int rank)
{
    if (!c || rank < 0 || rank >= HOSTS) {
        return 0;
    }
    service(c, rank);
    retire(c);
    return 1;
}

/* ------------------------------------------------------------------ digest */

static uint64_t fold_byte(uint64_t hash, uint8_t value)
{
    return (hash ^ (uint64_t)value) * UINT64_C(1099511628211);
}

static uint64_t fold_u64(uint64_t hash, uint64_t value)
{
    for (int j = 0; j < 8; j++) {
        hash = fold_byte(hash, (uint8_t)(value & 0xffu));
        value >>= 8;
    }
    return hash;
}

uint64_t collector_digest(collector_t *c)
{
    uint64_t h = UINT64_C(14695981039346656037);
    if (!c) {
        return h;
    }
    for (uint32_t p = c->b; p < c->K; p++) {
        const slot_t *s = slot_find(c, p);
        if (!s) {
            continue;
        }
        h = fold_u64(h, p);
        h = fold_byte(h, s->mask);
        h = fold_byte(h, s->complete);
        if (c->primitive == EPIC_PRIM_ALLGATHER) {
            for (int r = 0; r < HOSTS; r++) {
                h = fold_byte(h, s->raw[r] ? 1u : 0u);
                if (s->raw[r]) {
                    for (size_t j = 0; j < (size_t)c->D * 4u; j++) {
                        h = fold_byte(h, s->raw[r][j]);
                    }
                }
            }
        } else if (c->primitive == EPIC_PRIM_BCAST) {
            const uint8_t *raw = s->raw[c->root];
            if (raw) {
                for (size_t j = 0; j < (size_t)c->D * 4u; j++) {
                    h = fold_byte(h, raw[j]);
                }
            }
        } else {
            for (uint32_t j = 0; j < c->D; j++) {
                uint32_t v = s->agg ? s->agg[j] : 0u;
                for (int k = 0; k < 4; k++) {
                    h = fold_byte(h, (uint8_t)(v & 0xffu));
                    v >>= 8;
                }
            }
        }
    }
    return h;
}

/* ------------------------------------------------------------------- state */

void collector_state(collector_t *c, uint64_t *state)
{
    if (!state) {
        return;
    }
    memset(state, 0, 32u * sizeof(uint64_t));
    if (!c) {
        return;
    }
    state[0] = c->b;
    state[1] = c->occupied;
    for (int r = 0; r < HOSTS; r++) {
        state[2 + r] = c->R[r];
        state[6 + r] = c->S[r];
        state[10 + r] = c->A[r];
        state[14 + r] = c->U[r];
    }
    for (int i = 18; i < 32; i++) {
        state[i] = c->st[i];
    }
}

/* -------------------------------------------------------------------- open */

collector_t *collector_open(int primitive, int mode, int root, uint32_t count,
                            uint32_t words, uint32_t capacity, uint32_t start,
                            epic_emit_fn emit, void *user)
{
    collector_t *c = calloc(1, sizeof(*c));
    if (!c) {
        return NULL;
    }
    c->primitive = primitive;
    c->mode = mode;
    c->root = root;
    c->K = count;
    c->D = words;
    c->N = capacity ? capacity : 1u;
    c->start = start & MASK24;
    c->emit = emit;
    c->user = user;
    c->slots = calloc(c->N, sizeof(slot_t));
    c->frame_cap = sizeof(epic_eth_t) + sizeof(epic_ipv4_t) + sizeof(epic_udp_t) +
                   sizeof(epic_bth_t) + (size_t)EPIC_MAX_PAYLOAD_BYTES + 64u;
    c->frame = malloc(c->frame_cap);
    c->scratch = malloc((size_t)c->D * 4u + 16u);
    if (!c->slots || !c->frame || !c->scratch) {
        collector_close(c);
        return NULL;
    }
    for (int r = 0; r < HOSTS; r++) {
        epic_port_t *p = &c->ports[r];
        p->rank = r;
        p->host_mac[0] = 2;
        p->host_mac[1] = p->host_mac[2] = p->host_mac[3] = p->host_mac[4] = 0;
        p->host_mac[5] = (uint8_t)(r + 1);
        p->switch_mac[0] = 2;
        p->switch_mac[1] = 1;
        p->switch_mac[2] = p->switch_mac[3] = p->switch_mac[4] = 0;
        p->switch_mac[5] = (uint8_t)(r + 1);
        p->host_ip = htonl(0x0a000001u + (uint32_t)r);
        p->switch_ip = htonl(0x0a000065u + (uint32_t)r);
        p->host_qpn = 0x100u + (uint32_t)r;
        p->switch_qpn = 0x200u + (uint32_t)r;
    }
    return c;
}

void collector_close(collector_t *c)
{
    if (!c) {
        return;
    }
    if (c->slots) {
        for (uint32_t i = 0; i < c->N; i++) {
            slot_release(c, &c->slots[i]);
        }
        free(c->slots);
    }
    free(c->frame);
    free(c->scratch);
    free(c);
}
